        "titleIt": "Tour della capitale imperiale da Casablanca a Rabat",
        "descriptionIt": "Dopo la colazione partenza per Rabat, la capitale politica del Marocco. Esplora i siti storici tra cui la grande Torre Hassan, il Mausoleo di Mohammed V e la pittoresca Kasbah blu e bianca degli Udaya. Passeggia tra le stradine tranquille e goditi la vista panoramica sul fiume Bou Regreg.",
        "titleZh": "卡萨布兰卡至拉巴特帝国首都之旅",
