        "titleIt": "Da Rabat a Chefchaouen attraverso le montagne del Rif",
        "descriptionIt": "Viaggia verso nord da Rabat attraverso lo spettacolare scenario delle montagne del Rif fino alla famosa città dipinta di blu di Chefchaouen. Nel pomeriggio, esplora le splendide stradine della medina imbiancate di blu, rilassati in piazza Uta el-Hammam e curiosa nei negozi di artigianato locale alla ricerca di souvenir unici.",
        "titleZh": "拉巴特经里夫山脉到舍夫沙万",
