        "titleZh": "舍夫沙万经瓦鲁比利斯罗马遗址前往非斯",
        "descriptionZh": "离开蓝色之城，前往非斯。途中，参观被联合国教科文组织列为世界遗产的瓦卢比利斯古罗马遗址，那里有保存完好的马赛克。接下来，在皇城梅克内斯停留，欣赏宏伟的曼苏尔城门，然后抵达传统的非斯里亚德。"
