        "descriptionEs": "Cruce las montañas del Alto Atlas por el pintoresco paso de Tizi n'Tichka (2260 m). Visite la mundialmente famosa Kasbah Ait Benhaddou, una fortaleza tradicional de arcilla, declarada Patrimonio de la Humanidad por la UNESCO. Continúe por Ouarzazate y el Valle de las Rosas para llegar a las gargantas del Dades y pasar la noche.",
        "titleIt": "Da Marrakech alla Valle del Dades via Ait Benhaddou",
        "descriptionIt": "Attraversa le montagne dell'Alto Atlante attraverso il panoramico passo Tizi n'Tichka (2.260 m). Visita la famosa Kasbah Ait Benhaddou, dichiarata Patrimonio dell'Umanità dall'UNESCO, una tradizionale roccaforte di argilla. Prosegui attraverso Ouarzazate e la Valle delle Rose per arrivare alle gole del Dades per il pernottamento.",
        "titleZh": "马拉喀什经艾特本哈杜前往达德斯山谷",
        "descriptionZh": "通过风景秀丽的 Tizi n'Tichka 山口 (2,260m) 穿越高阿特拉斯山脉。参观世界著名的联合国教科文组织列为世界遗产的艾特本哈杜古堡，这是一个传统的粘土堡垒。继续穿过瓦尔扎扎特和玫瑰谷，抵达达德斯峡谷过夜。"
