        "descriptionEs": "¡Bienvenidos a Marruecos! A su llegada al aeropuerto de Casablanca, su chófer y guía profesional privado lo recibirá. Comience su recorrido con una visita a la icónica Mezquita Hassan II, una obra maestra de la arquitectura marroquí situada directamente en la costa atlántica. Traslado a su cómodo hotel de lujo de 5 estrellas/riad privado de lujo premium para el check-in y tiempo libre.",
        "titleIt": "Arrivo a Casablanca e Moschea Hassan II",
        "descriptionIt": "Benvenuti in Marocco! All'arrivo all'aeroporto di Casablanca, verrai accolto dal tuo autista e guida professionale privato. Inizia il tuo tour con una visita all'iconica Moschea Hassan II, un capolavoro dell'architettura marocchina situato direttamente sulla costa atlantica. Trasferimento al tuo confortevole hotel di lusso a 5 stelle/riad privato di lusso premium per il check-in e il tempo libero.",
        "titleZh": "抵达卡萨布兰卡和哈桑二世清真寺",
        "descriptionZh": "欢迎来到摩洛哥！抵达卡萨布兰卡机场后，您的私人专业司机和导游将迎接您。首先参观标志性的哈桑二世清真寺，这是摩洛哥建筑的杰作，位于大西洋海岸。转移到您舒适的豪华五星级酒店/高级豪华私人里亚德办理入住手续并享受休闲时光。"
